<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Assistant\Port\AssistantProviderInterface;use App\Domain\Assistant\ValueObject\SyllabusEvidence;use App\Domain\Catalog\Entity\Position;use App\Domain\Catalog\Entity\Subject;use App\Domain\Catalog\Repository\PositionRepositoryInterface;use App\Domain\Catalog\Repository\SubjectRepositoryInterface;use App\Domain\Catalog\Repository\SubjectTaxonomyAssignmentRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusDocumentExtractionRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;
final class AnalyzeSyllabusCatalogService { public function __construct(private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusDocumentExtractionRepositoryInterface $extractions,private readonly PositionRepositoryInterface $positions,private readonly SubjectRepositoryInterface $subjects,private readonly TaxonomySubjectRepositoryInterface $taxonomy,private readonly SubjectTaxonomyAssignmentRepositoryInterface $assignments,private readonly SubjectTaxonomyService $slugs,private readonly AssistantProviderInterface $ai){} public function analyze(string $syllabusId):void{$syllabus=$this->syllabi->findById($syllabusId);if($syllabus===null)throw new \DomainException('Edital nao encontrado.');$pages=$this->extractions->listForSyllabus($syllabusId);if($pages===[])throw new \DomainException('Edital sem texto extraido.');$this->savePositions($syllabus->examId,$this->positionsFrom($pages));$this->saveSubjects($syllabusId,$this->subjectsFrom($pages));}
private function positionsFrom(array $pages):array{$data=$this->ask('Retorne somente JSON: {"positions":["nome"]}. Extraia todas as ÊNFASES do QUADRO 1 - VAGAS no ANEXO I. Cada ênfase é um cargo distinto; preserve número e texto. Não inclua o cargo-base genérico.',$this->annex($pages,'ANEXO I','ANEXO II'));return array_values(array_filter($data['positions']??[],fn($v)=>is_string($v)&&$this->valid($v)));}
private function subjectsFrom(array $pages):array{$items=[];foreach(array_chunk($this->annex($pages,'ANEXO IV','ANEXO V'),2) as $chunk){$data=$this->ask('Retorne somente JSON: {"subjects":[{"name":"nome genérico","parent":"possível pai ou null","kind":"MATTER|TOPIC|SUBTOPIC","page":59}]}. Extraia uma taxonomia semântica do conteúdo destas páginas. Nunca inclua cargo, ênfase, empresa, edital, Conhecimentos Básicos ou Conhecimentos Específicos: eles não são nós desta árvore. Crie matéria apenas quando o próprio conteúdo a sustentar; parent pode ser uma sugestão de matéria mais ampla já existente. Remova toda numeração editorial. Decomponha itens compostos: por exemplo, Redes de Computadores e Sistemas Distribuídos deve conter Sistemas Distribuídos sob Redes de Computadores; protocolos TCP/IP, DNS, FTP e HTTP devem ficar sob Redes/Protocolos, sem duplicar o assunto pai. Una blocos repetidos como Segurança da Informação e transforme listas longas em subassuntos sem repetir nomes. Use áreas amplas apenas quando sustentadas: Direito é pai de Direito Constitucional, Administrativo, Penal e Civil; Tecnologia da Informação é pai de Redes de Computadores, Banco de Dados, Segurança da Informação e Desenvolvimento; Língua Portuguesa é pai de Gramática, Interpretação de Textos, Sintaxe e Morfologia. Preserve esses ramos e não duplique nós equivalentes.',$chunk);if(is_array($data['subjects']??null))$items=array_merge($items,$data['subjects']);}return array_slice($items,0,500);}
private function ask(string $prompt,array $evidence):array{$answer=$this->ai->answer($prompt,$evidence)->content;$mark=chr(96).chr(96).chr(96);$json=trim(str_replace([$mark.'json',$mark],'',$answer));$data=json_decode($json,true,512,JSON_THROW_ON_ERROR);if(!is_array($data))throw new \DomainException('A IA nao retornou estrutura valida.');return $data;}
private function annex(array $pages,string $start,string $end):array{$active=false;$out=[];foreach($pages as $page){$header=mb_substr($page->textContent,0,1000);if(preg_match('/'.preg_quote($start,'/').'/iu',$header))$active=true;if($active&&preg_match('/'.preg_quote($end,'/').'/iu',$header))break;if($active)$out[]=new SyllabusEvidence($page->pageNumber,mb_substr($page->textContent,0,12000));}if($out===[])throw new \DomainException('Anexo necessario nao encontrado.');return $out;}
private function savePositions(string $examId,array $names):void{$known=array_map(fn($p)=>$this->key($p->name),$this->positions->listForExam($examId));foreach($names as $name){$name=$this->label($name);if(in_array($this->key($name),$known,true))continue;$this->positions->save(new Position($this->id(),$examId,$name,null));$known[]=$this->key($name);}}
private function saveSubjects(string $syllabusId,array $items):void{$planned=[];foreach($items as $item){if(!is_array($item)||!is_string($item['name']??null)||!$this->valid($item['name']))continue;$name=$this->label($item['name']);$planned[$this->key($name)]=['name'=>$name,'parent'=>is_string($item['parent']??null)&&$this->valid($item['parent'])?$this->label($item['parent']):null,'page'=>max(1,(int)($item['page']??1))];}$local=[];$canonical=[];$order=0;foreach($planned as $item)$this->ensureSubject($syllabusId,$item['name'],$planned,$local,$canonical,$order);}
private function ensureSubject(string $syllabusId,string $name,array $planned,array &$local,array &$canonical,int &$order):Subject{$key=$this->key($name);if(isset($local[$key]))return $local[$key];$item=$planned[$key]??['name'=>$name,'parent'=>null,'page'=>1];$parentSubject=null;$parentTax=null;if($item['parent']!==null&&$this->key($item['parent'])!==$key){$parentSubject=$this->ensureSubject($syllabusId,$item['parent'],$planned,$local,$canonical,$order);$parentTax=$canonical[$this->key($item['parent'])]??null;}$slug=$this->slugs->slug($item['name']);$tax=$this->taxonomy->findByParentAndSlug($parentTax?->id,$slug)??$this->taxonomy->findBySlug($slug)??$this->taxonomy->findByComparableSlug($slug);if($tax===null){$tax=new TaxonomySubject($this->id(),$parentTax?->id,$item['name'],$slug,null,$parentTax===null?0:$parentTax->level+1,true);$this->taxonomy->save($tax);}$subject=new Subject($this->id(),$syllabusId,$parentSubject?->id,$item['name'],$order++,null,$item['page']);$this->subjects->save($subject);$this->assignments->replaceForSubject($subject->id,[$tax->id]);$local[$key]=$subject;$canonical[$key]=$tax;return $subject;}
private function valid(string $name):bool{$name=trim($name);return mb_strlen($name)>2&&mb_strlen($name)<191;}private function label(string $name):string{$name=preg_replace('/^\s*(?:\d+(?:\.\d+)*[.)-]?|[IVXLCDM]+[.)-]?|[a-z][.)-])\s+/iu','',$name)??$name;return trim(preg_replace('/\s+/u',' ',$name)??$name, " \t\n\r\0\x0B:;-");}private function root(string $name):bool{return in_array($this->key($name),['conhecimentos basicos','conhecimentos especificos'],true);}private function key(string $name):string{$name=mb_strtolower($this->label($name));return strtr($name,['á'=>'a','à'=>'a','â'=>'a','ã'=>'a','ä'=>'a','é'=>'e','è'=>'e','ê'=>'e','ë'=>'e','í'=>'i','ì'=>'i','î'=>'i','ï'=>'i','ó'=>'o','ò'=>'o','ô'=>'o','õ'=>'o','ö'=>'o','ú'=>'u','ù'=>'u','û'=>'u','ü'=>'u','ç'=>'c']);}private function id():string{return bin2hex(random_bytes(16));}}
